cd /Users/kristinarash/Library/Caches/sportsci-batch-99 && cat > helpers/v3/validate.py <<'EOF'
import json,sys
base=sys.argv[1]
inp={x['id']:x for x in json.load(open(base+'/inputs.json'))}
tax=json.load(open(base+'/taxonomy.json'))
ok=True
for i in ['Q17','Q18','Q19','Q20','Q21','Q22','Q23','Q24']:
    d=json.load(open(f'{base}/verified/{i}.json',encoding='utf-8'))
    e=[]
    if d['sourceFile']!=inp[i]['sourceFile']: e.append('sourceFile')
    if d['id']!=i: e.append('id')
    if d['decision'] not in ('INCLUDE','EXCLUDE','DEGRADED'): e.append('decision')
    if d['decision']!='EXCLUDE':
        if d['primaryDomain'] not in d['domains']: e.append('primaryDomain')
        for k,t in [('domains','domains'),('audiences','audiences'),('sports','sports'),('populations','populations')]:
            for v in d[k]:
                if v not in tax[t]: e.append(f'{k}:{v}')
        if d['studyDesign'] not in tax['studyDesigns']: e.append('studyDesign')
    v=d['verification']
    if v['status'] not in ('VERIFIED','CORRECTED','DECISION_CHANGED'): e.append('status')
    if v['spotCheckPriority'] not in ('high','normal'): e.append('prio')
    s=json.dumps({k:x for k,x in d.items() if k!='sourceFile'},ensure_ascii=False)
    if '—' in s: e.append('emdash')
    if d['decision']=='DEGRADED' and not d['degradedReason']: e.append('degradedReason')
    print(i,d['decision'],v['status'],v['spotCheckPriority'],e or 'OK')
EOF
python3 -I helpers/v3/validate.py "$PWD"; git -C "$PWD" status 2>&1 | head -2

